// Vercel build step: point the static pages at the backend named by DEMO_API_URL.
// The pages themselves are generated by scripts/build_frontend.py and committed.
import { writeFileSync } from "node:fs";

const api = (process.env.DEMO_API_URL || "https://junior-ml-dev-demo.onrender.com").replace(/\/$/, "");
if (!/^https?:\/\/[^\s"'<>]+$/.test(api)) throw new Error("DEMO_API_URL must be an http(s) URL");
writeFileSync(new URL("./demo-assets/config.js", import.meta.url), `window.JMD_API = ${JSON.stringify(api)};\n`);
console.log("backend:", api);
